PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS territories(id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY, name TEXT NOT NULL, domain TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS account_domain ON accounts(domain);
CREATE TABLE IF NOT EXISTS account_relationships(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), related_account_id TEXT REFERENCES accounts(id), relation TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS facilities(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), country TEXT, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS connectors(id TEXT PRIMARY KEY, enabled INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, origin TEXT NOT NULL, family TEXT NOT NULL, connector_id TEXT REFERENCES connectors(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_runs(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), state TEXT NOT NULL, created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, account_id TEXT REFERENCES accounts(id), source_id TEXT NOT NULL REFERENCES sources(id), canonical_url TEXT NOT NULL, fingerprint TEXT NOT NULL, review_status TEXT NOT NULL, data TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS account_document_url ON documents(account_id,canonical_url);
CREATE TABLE IF NOT EXISTS document_versions(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), fingerprint TEXT NOT NULL, retrieved_at TEXT NOT NULL, run_id TEXT REFERENCES research_runs(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claims(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), document_id TEXT NOT NULL REFERENCES documents(id), review_status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), cluster_key TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(account_id,cluster_key));
CREATE TABLE IF NOT EXISTS event_evidence(event_id TEXT NOT NULL REFERENCES events(id), document_id TEXT NOT NULL REFERENCES documents(id), PRIMARY KEY(event_id,document_id));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), event_id TEXT REFERENCES events(id), product_id TEXT REFERENCES products(id), analyst_status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS opportunity_evidence(opportunity_id TEXT NOT NULL REFERENCES opportunities(id), document_id TEXT NOT NULL REFERENCES documents(id), relationship TEXT NOT NULL CHECK(relationship IN ('supports','contradicts','context')), PRIMARY KEY(opportunity_id,document_id,relationship));
CREATE TABLE IF NOT EXISTS buyer_roles(id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS competitive_constraints(id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analyst_notes(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), opportunity_id TEXT REFERENCES opportunities(id), created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scoring_policies(id TEXT PRIMARY KEY, created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS score_snapshots(id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), policy_id TEXT NOT NULL REFERENCES scoring_policies(id), created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_metadata(key TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS runs_state ON research_runs(state,created_at);
CREATE INDEX IF NOT EXISTS document_account ON documents(account_id);
CREATE INDEX IF NOT EXISTS opportunity_account ON opportunities(account_id);
